// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount, address receiver) public {
        vm.assume(receiver != address(0) && amount > 0 && amount <= 1e30);
        // Setup: mint some tokens and deposit so there is something to claim
        // For simplicity we just test the pause/unpause logic directly
        // First, pause the contract
        address keeper = c.keeper();
        vm.prank(keeper);
        c.pauseDeposit();
        // Now unpause via the keeper
        vm.prank(keeper);
        c.unpauseDeposit();
        // The general rule: after calling unpauseDeposit(), the contract must be unpaused
        assertTrue(!c.paused());
    }
}

